def cheapest_quote(n):
    prices = {
        40: 3.85,
        20: 1.93,
        10: 0.97,
        5: 0.49,
        1: 0.10
    }

    cost_per_newspaper = {price: count for count, price in prices.items()}
    total_cost = float('inf')

    while n > 0:
        best_option = min(cost_per_newspaper, key=lambda x: x[0] * cost_per_newspaper[x] if n >= cost_per_newspaper[x] else float('inf'))
