    # Check for Pentagonal Number
    def is_pentagonal(x):
        return (math.sqrt(24 * x + 1) + 1) % 6 == 0

    # Check for Generalized Pentagonal Number
    def is_generalized_pentagonal(x):
        i = 1
        while True:
            val = (3 * i * (i - 1)) / 2
            if val == x:
                return True
            if (3 * i + 1) * i / 2 == x:
                return True
            if val > x:
                return False
            i += 1

    # Check for Square Pentagonal Number
    def is_square_pentagonal(x):
        if not is_pentagonal(x):
            return False
        sqrt_x = int(math.sqrt(x))
        return sqrt_x * sqrt_x == x

    return is_pentagonal(n) or is_generalized_pentagonal(n) or is_square_pentagonal(n)
